package com.aaliyun.leadnews.article.web;
import com.aaliyun.leadnews.article.config.PublishProperties;import com.aaliyun.leadnews.article.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController public class ArticleStaticController{private final ArticleApplicationService articles;private final ArticleObjectStorage storage;private final PublishProperties props;public ArticleStaticController(ArticleApplicationService a,ArticleObjectStorage s,PublishProperties p){articles=a;storage=s;props=p;}
 @GetMapping("/static/article/{id}")public ResponseEntity<byte[]> html(@PathVariable Long id,HttpServletRequest request){String key=articles.staticObjectKey(id);ArticleObjectStorage.StoredObject o=storage.get(key);String etag="\""+o.etag()+"\"";if(etag.equals(request.getHeader(HttpHeaders.IF_NONE_MATCH)))return ResponseEntity.status(HttpStatus.NOT_MODIFIED).eTag(etag).cacheControl(CacheControl.maxAge(java.time.Duration.ofSeconds(props.cacheMaxAgeSeconds())).cachePublic()).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/html;charset=UTF-8")).eTag(etag).lastModified(o.lastModified()).cacheControl(CacheControl.maxAge(java.time.Duration.ofSeconds(props.cacheMaxAgeSeconds())).cachePublic()).body(o.bytes());}}
